'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');const boot=require('./runtime.cjs');
const captchaFixture=(id='test-captcha')=>({id,image:'data:image/png;base64,iVBORw0KGgo=',expiresAt:new Date(Date.now()+120000).toISOString()});
async function create(user,{unauthorized=false,storage}={}){const b=boot(storage),{ctx,elements,lists}=b;const classes=new Set();ctx.document.documentElement={classList:{add:x=>classes.add(x),remove:x=>classes.delete(x),contains:x=>classes.has(x)}};ctx.location={href:'https://www.siyuejn.com/crm/',origin:'https://www.siyuejn.com',hostname:'www.siyuejn.com'};ctx.Event=function(){};ctx.dispatchEvent=()=>{};ctx.SIYUE_AUTH_API='/crm-api/';ctx.localStorage.removeItem=key=>b.storage.delete(key);ctx.document.visibilityState='visible';ctx.document.getElementById=id=>ctx.document.querySelector('#'+id);ctx.document.querySelector('.account-trigger').removeAttribute=()=>{};const requests=[];ctx.fetch=async(url,options={})=>{requests.push({url:String(url),options});if(String(url).endsWith('/v1/auth/captcha'))return{ok:true,status:200,json:async()=>captchaFixture()};if(unauthorized)return{ok:false,status:401,json:async()=>({code:'AUTH_REQUIRED'})};if(String(url).endsWith('/v1/auth/password'))return{ok:true,status:200,json:async()=>user.mustChangePassword?{changed:true,reauthenticate:false,user:{...user,mustChangePassword:false,version:user.version+1},csrfToken:'rotated-csrf',expiresAt:'2099-01-01'}:{changed:true,reauthenticate:true}};return{ok:true,status:200,json:async()=>({user,csrfToken:'private-csrf',expiresAt:'2099-01-01'})}};b.run(fs.readFileSync(path.join(__dirname,'../employee-auth.js'),'utf8'));await new Promise(resolve=>setImmediate(resolve));return{...b,classes,requests,respond(fn){ctx.fetch=fn}}}
const user=(p=[],extra={})=>({id:'real-employee-1',name:'测试员工',username:'employee1',roleIds:['teacher'],permissions:p,scope:{type:'assigned',campusIds:[]},mustChangePassword:false,version:1,...extra});
test('account settings identify built-in roles before role directory is loaded',async()=>{const admin=await create(user(['dashboard.read','account.update','role.grant'],{roleIds:['superadmin'],scope:{type:'all'}}));await admin.run('employeeAuth.open()');assert.match(admin.elements.get('#view').innerHTML,/<p class="help">超级管理员<\/p>/);assert.doesNotMatch(admin.elements.get('#view').innerHTML,/未识别角色/)});
test('unauthenticated real mode locks old prototype and cannot keep admin authority',async()=>{const b=await create(null,{unauthorized:true});assert.equal(b.classes.has('employee-auth-locked'),true);assert.equal(b.run("permissionCanVisit('staff')"),false);assert.equal(b.run("workflowMay('payment')"),false);assert.match(b.elements.get('#employee-auth-gate').innerHTML,/员工登录/);assert.match(b.elements.get('#employee-auth-gate').innerHTML,/role="alert"><\/p>/)});
test('initial password blocks all business and displays full-page self change',async()=>{const b=await create(user(['dashboard.read'],{mustChangePassword:true}));assert.equal(b.classes.has('employee-auth-locked'),true);assert.equal(b.run("permissionCanVisit('home')"),false);assert.equal(b.run("workflowMay('academic')"),false);assert.match(b.elements.get('#employee-auth-gate').innerHTML,/设置自己的密码/)});
test('teacher exact permissions deny transfer and substitute while allowing owned attendance',async()=>{const b=await create(user(['dashboard.read','schedule.read','session.attendance','session.record']));assert.equal(b.classes.has('employee-auth-locked'),false);assert.equal(b.run("permissionCanVisit('tempMove')"),false);assert.equal(b.run('academicRepairMoveAllowed()'),false);assert.equal(b.run("workflowCommitMove()"),false);assert.equal(b.run("workflowConfirmSubstitute()"),false);assert.equal(b.run("workflowMay('academic')"),true);assert.equal(b.run("batchAllowed('transfer')"),false);assert.equal(b.run("commandAllowed({label:'临时调课／调班',page:'tempMove'})"),false);assert.equal(b.run('workflowCurrentActor().id'),'real-employee-1')});
test('real lead ownership uses stable employee ids and rejects same-name unrelated records',async()=>{const b=await create(user(['dashboard.read','lead.read','lead.follow'],{roleIds:['sales'],scope:{type:'own'}}));assert.equal(b.run("workflowCanReadLead({owner:'测试员工'})"),false);assert.equal(b.run("workflowCanReadLead({ownerId:'real-employee-1'})"),true);assert.equal(b.run("workflowCanReadLead({ownerId:'different',owner:'测试员工'})"),false);b.run("accountSwitchIdentity('admin')");assert.equal(b.run("permissionCanVisit('staff')"),false)});
test('refresh keeps in-progress forms; session invalidation locks immediately',async()=>{const b=await create(user(['dashboard.read']));b.elements.get('#view').innerHTML='UNSAVED_FORM';await b.run('employeeAuth.refresh()');assert.equal(b.elements.get('#view').innerHTML,'UNSAVED_FORM');b.respond(async()=>({ok:false,status:401,json:async()=>({code:'SESSION_EXPIRED'})}));await assert.rejects(b.run('employeeAuth.refresh()'));assert.equal(b.classes.has('employee-auth-locked'),true);assert.equal(b.run('workflowCurrentActor()'),null)});
test('account creation sends role, scope, overrides with CSRF and escapes one-time credentials',async()=>{const b=await create(user(['dashboard.read','employee.create','account.update','role.grant'],{roleIds:['superadmin'],scope:{type:'all'}}));const requests=[];const roles=[{id:'sales',label:'销售',description:'本人线索'}];b.respond(async(url,options={})=>{requests.push({url:String(url),options});const endpoint=String(url);return{ok:true,status:200,json:async()=>endpoint.endsWith('/v1/roles')?{roles,permissions:[{id:'lead.follow',label:'跟进'}]}:options.method==='POST'?{user:{id:'new-user',username:'sy-unsafe" autofocus x="',name:'员工',roleIds:['sales'],permissions:[],scope:{type:'own'}},initialPassword:'A-password"<&123'}:{users:[]}}});await b.run('employeeAuth.openAccounts()');b.run('employeeAuth.newAccount()');b.ctx.document.querySelector('#ea-name').value='测试名字';b.ctx.document.querySelector('#ea-scope').value='own';b.lists.set('input[name="ea-role"]:checked',[{value:'sales'}]);b.lists.set('[name="ea-override"]',[{value:'deny',dataset:{permission:'lead.follow'}}]);await b.run('employeeAuth.saveAccount()');const post=requests.find(x=>x.options.method==='POST');assert.equal(post.options.credentials,'same-origin');assert.equal(post.options.headers['X-CSRF-Token'],'private-csrf');assert.deepEqual(JSON.parse(post.options.body).deniedPermissions,['lead.follow']);assert.match(b.elements.get('#view').innerHTML,/&quot;/);assert.ok(!b.elements.get('#view').innerHTML.includes('value="sy-unsafe" autofocus'));assert.deepEqual(JSON.parse(b.run('JSON.stringify(workspaceFields())')),[]);assert.equal(b.storage.get('private-csrf'),undefined)});
test('logout and identity changes clear admin directories, audit data and hidden credential DOM',async()=>{const admin=user(['dashboard.read','employee.create','account.update','role.grant'],{roleIds:['superadmin'],scope:{type:'all'}});const b=await create(admin);b.respond(async(url)=>({ok:true,status:200,json:async()=>String(url).endsWith('/v1/roles')?{roles:[],permissions:[]}:{users:[{id:'private-other',username:'private-directory',name:'秘密员工',roleIds:['sales'],scope:{type:'own'}}]}}));await b.run('employeeAuth.openAccounts()');assert.equal(b.run('employeeAuthDirectory().length'),1);b.elements.get('#view').innerHTML='INITIAL_PASSWORD_SECRET';await b.run('employeeAuth.logout()');assert.equal(b.run('employeeAuthDirectory().length'),0);assert.equal(b.elements.get('#view').innerHTML,'');await new Promise(resolve=>setImmediate(resolve));const sales=user(['dashboard.read','lead.read'],{id:'sales-other',roleIds:['sales'],scope:{type:'own'}});b.respond(async url=>({ok:true,status:200,json:async()=>String(url).endsWith('/v1/auth/captcha')?captchaFixture('sales-captcha'):{user:sales,csrfToken:'new'}}));await b.run('employeeAuth.refreshCaptcha()');b.ctx.document.querySelector('#ea-captcha-code').value='123456';b.ctx.document.querySelector('#ea-username').value='sales';b.ctx.document.querySelector('#ea-password').value='password';await b.run('employeeAuth.login()');assert.equal(b.run('workflowCurrentActor().id'),'sales-other');assert.equal(b.run('employeeAuthDirectory().length'),0);assert.ok(!b.elements.get('#view').innerHTML.includes('private-directory'));assert.ok(!b.elements.get('#view').innerHTML.includes('INITIAL_PASSWORD_SECRET'));});
test('late admin response cannot restore directory after an expired session',async()=>{const b=await create(user(['dashboard.read','account.update'],{roleIds:['superadmin'],scope:{type:'all'}}));let finish;b.respond(async(url)=>String(url).endsWith('/v1/admin/users')?new Promise(resolve=>finish=resolve):{ok:true,status:200,json:async()=>({roles:[],permissions:[]})});const pending=b.run('employeeAuth.openAccounts()');await new Promise(resolve=>setImmediate(resolve));b.respond(async()=>({ok:false,status:401,json:async()=>({code:'SESSION_EXPIRED'})}));await assert.rejects(b.run('employeeAuth.refresh()'));finish({ok:true,status:200,json:async()=>({users:[{id:'private'}]})});await pending;assert.equal(b.run('employeeAuthDirectory().length'),0);assert.equal(b.classes.has('employee-auth-locked'),true);assert.equal(b.elements.get('#view').innerHTML,'')});
test('delegated audit.read gets Chinese summaries without exposing actor or target ids in content',async()=>{const b=await create(user(['dashboard.read','audit.read'],{roleIds:['auditor']}));assert.equal(b.run("permissionCanVisit('permissionLogs')"),true);assert.equal(b.run("commandAllowed({label:'查看操作日志',page:'permissionLogs'})"),true);assert.equal(b.run("permissionCanVisit('staff')"),false);b.respond(async()=>({ok:true,status:200,json:async()=>({events:[{id:'event-private',at:'2026-10-10T00:00:00Z',actorId:'user-private',actorName:'张老师',action:'auth.login',targetId:'target-private',outcome:'success',summary:{changes:[{collection:'orders',id:'secret-order',name:'秋季体验课报名单'}]}}]})}));await b.run('employeeAuth.openAudit()');const html=b.elements.get('#view').innerHTML;assert.match(html,/员工登录/);assert.match(html,/张老师/);assert.match(html,/2026\/10\/10 08:00:00/);assert.match(html,/秋季体验课报名单/);assert.match(html,/日常操作/);assert.match(html,/需要关注/);assert.match(html,/全部记录/);assert.doesNotMatch(html,/<td>(?:user-private|target-private|auth\.login)<\/td>|\[object Object\]|secret-order/);b.run('employeeAuth.toggleAudit(0)');assert.match(b.elements.get('#view').innerHTML,/涉及 收款与订单：秋季体验课报名单/);assert.ok(!html.includes('onclick="employeeAuth.openAccounts()"'));});

test('course creation and editing respect separate grants; scheduling command is permission bound',async()=>{const editor=await create(user(['course.read','course.update']));editor.run("a.selectedClass=null");assert.equal(editor.run('saveCourse()'),false);assert.equal(editor.messages.at(-1),'当前账号没有此操作权限');editor.run("a.selectedClass=0");editor.run('saveCourse()');assert.notEqual(editor.messages.at(-1),'当前账号没有此操作权限');const creator=await create(user(['course.read','course.create']));creator.run('a.selectedClass=0');assert.equal(creator.run('saveCourse()'),false);assert.equal(creator.messages.at(-1),'当前账号没有此操作权限');const scheduler=await create(user(['class.read','class.create','schedule.read']));assert.equal(scheduler.run("commandAllowed({id:'action.classes.schedule',label:'班级排课',page:'classes'})"),true);const viewer=await create(user(['class.read','schedule.read']));assert.equal(viewer.run("commandAllowed({id:'action.classes.schedule',label:'班级排课',page:'classes'})"),false);assert.equal(viewer.run('academicScheduleSave()'),false)});

