test('audit filters map person search and action groups to compatible query params and keep server cursors',async()=>{const b=await create(user(['audit.read']));const urls=[];b.respond(async(url)=>{urls.push(String(url));return {ok:true,status:200,json:async()=>({events:[{at:'2026-10-10',actorName:'张老师',action:'auth.login',outcome:'success'}],nextBefore:String(url).includes('before=')?null:'next-row'})}});b.ctx.document.querySelector('#ea-audit-actor').value='张老师';b.ctx.document.querySelector('#ea-audit-action').value='auth.';b.ctx.document.querySelector('#ea-audit-result').value='success';await b.run('employeeAuth.filterAudit()');assert.match(b.elements.get('#view').innerHTML,/value="张老师"/);assert.match(b.elements.get('#view').innerHTML,/value="success" selected/);await b.run('employeeAuth.auditPage(1)');assert.match(urls.at(-1),/before=next-row/);assert.match(urls.at(-1),/actorQuery=.%E8%80%81%E5%B8%88|actorQuery=%E5%BC%A0%E8%80%81%E5%B8%88/);assert.match(urls.at(-1),/actionPrefix=auth\./);await b.run('employeeAuth.auditPage(-1)');assert.ok(!urls.at(-1).includes('before='));b.ctx.document.querySelector('#ea-audit-from').value='2026-11-10';b.ctx.document.querySelector('#ea-audit-to').value='2026-10-10';const length=urls.length;await b.run('employeeAuth.filterAudit()');assert.equal(urls.length,length);assert.match(b.elements.get('#view').innerHTML,/开始日期不能晚于/) });


