test('position workspace shows immutable role duties and opens employee assignment without auto-saving',async()=>{const admin=user(['account.update','role.grant'],{roleIds:['superadmin'],scope:{type:'all'}}),b=await create(admin),roles=[{id:'teacher',label:'教师',description:'负责本人授课和考勤',defaultScope:'assigned',permissions:['session.attendance']},{id:'sales',label:'销售',description:'跟进本人线索',defaultScope:'own',permissions:['lead.follow']}],staff={id:'staff-1',name:'甲老师',username:'teacher-a',employeeNo:'T01',roleIds:['teacher'],scope:{type:'assigned',campusIds:[]},additionalPermissions:[],deniedPermissions:[],permissions:['session.attendance']};let writes=0;b.respond(async(url,options={})=>{const endpoint=String(url);if(endpoint.endsWith('/v1/roles'))return{ok:true,status:200,json:async()=>({roles,permissions:[{id:'session.attendance',label:'登记考勤'},{id:'lead.follow',label:'跟进线索'},{id:'lead.create',label:'创建线索'}]})};if(endpoint.endsWith('/v1/admin/users')&&options.method==='GET')return{ok:true,status:200,json:async()=>({users:[staff]})};writes++;return{ok:true,status:200,json:async()=>({user:staff})}});await b.run("employeeAuth.openDirectory('positions')");assert.match(b.elements.get('#view').innerHTML,/职位管理/);assert.match(b.elements.get('#view').innerHTML,/负责本人授课和考勤/);assert.match(b.elements.get('#view').innerHTML,/登记考勤/);assert.match(b.elements.get('#view').innerHTML,/甲老师/);assert.match(b.elements.get('#view').innerHTML,/新建员工并预选岗位/);b.run("employeeAuth.editWithRole('staff-1','sales')");assert.match(b.elements.get('#view').innerHTML,/name="ea-role" value="sales"[^>]*checked/);assert.equal(writes,0);assert.equal(b.run('state.page'),'staff');await b.run("employeeAuth.newAccount('sales')");assert.match(b.elements.get('#view').innerHTML,/value="sales"[^>]*checked/)});

test('permission workspace distinguishes role preview, preserves drafts across employee switches, and saves overrides',async()=>{const admin=user(['account.update','role.grant'],{roleIds:['superadmin'],scope:{type:'all'}}),b=await create(admin),roles=[{id:'teacher',label:'教师',description:'本人授课',defaultScope:'assigned',permissions:['session.attendance']},{id:'sales',label:'销售',description:'本人线索',defaultScope:'own',permissions:['lead.follow']}],staff={id:'staff-1',name:'甲老师',username:'teacher-a',roleIds:['teacher'],scope:{type:'assigned',campusIds:[]},additionalPermissions:[],deniedPermissions:[],permissions:['session.attendance']},other={id:'staff-2',name:'乙老师',username:'teacher-b',roleIds:['teacher'],scope:{type:'assigned',campusIds:[]},additionalPermissions:[],deniedPermissions:[],permissions:['session.attendance']};let update;b.respond(async(url,options={})=>{const endpoint=String(url);if(endpoint.endsWith('/v1/roles'))return{ok:true,status:200,json:async()=>({roles,permissions:[{id:'session.attendance',label:'登记考勤'},{id:'lead.follow',label:'跟进线索'}]})};if(endpoint.endsWith('/v1/admin/users')&&options.method==='GET')return{ok:true,status:200,json:async()=>({users:[staff,other]})};update={endpoint,options,body:JSON.parse(options.body||'{}')};return{ok:true,status:200,json:async()=>({user:{...staff,...update.body}})}});await b.run("employeeAuth.openDirectory('permissions')");assert.match(b.elements.get('#view').innerHTML,/教师 · 权限模板/);assert.match(b.elements.get('#view').innerHTML,/employee-permission-tree/);assert.match(b.elements.get('#view').innerHTML,/在岗人员：2 人/);assert.match(b.elements.get('#view').innerHTML,/name=\"ea-role-permission\"[^>]*checked/);assert.match(b.elements.get('#view').innerHTML,/保存权限更改/);assert.match(b.elements.get('#view').innerHTML,/员工授权/);b.run("employeeAuth.selectPermissionEmployee('staff-1')");assert.match(b.elements.get('#view').innerHTML,/员工单项权限/);b.lists.set('input[name="ea-role"]:checked',[{value:'teacher'},{value:'sales'}]);b.lists.set('[name="ea-override"]',[{value:'deny',dataset:{permission:'session.attendance'}}]);b.run("employeeAuth.selectPermissionEmployee('staff-2')");assert.match(b.elements.get('#view').innerHTML,/乙老师/);b.run("employeeAuth.selectPermissionEmployee('staff-1')");assert.match(b.elements.get('#view').innerHTML,/value="sales"[^>]*checked/);assert.match(b.elements.get('#view').innerHTML,/value="deny" selected/);const snapshot=b.run('employeeAuth.captureRoute()');b.run("employeeAuth.selectPermissionRole('sales')");b.run('employeeAuth.restoreRoute(JSON.parse('+JSON.stringify(JSON.stringify(snapshot))+'))');await b.run('employeeAuth.renderCurrent()');assert.match(b.elements.get('#view').innerHTML,/value="sales"[^>]*checked/);b.lists.set('input[name="ea-role"]:checked',[{value:'teacher'}]);b.lists.set('[name="ea-override"]',[{value:'deny',dataset:{permission:'session.attendance'}}]);b.ctx.document.querySelector('#ea-name').value='甲老师';b.ctx.document.querySelector('#ea-scope').value='assigned';await b.run('employeeAuth.saveAccount()');assert.equal(update.endpoint.endsWith('/v1/admin/users/staff-1'),true);assert.deepEqual(update.body.deniedPermissions,['session.attendance']);assert.equal(b.run('state.page'),'permissions');assert.match(b.elements.get('#view').innerHTML,/员工单项权限/)});


test('role template edits preserve drafts, save with version and CSRF, and keep admin role fixed',async()=>{const admin=user(['account.update','role.grant'],{roleIds:['superadmin'],scope:{type:'all'}}),b=await create(admin);let roles=[{id:'teacher',label:'教师',description:'默认授课',defaultScope:'assigned',permissions:['session.attendance','lead.follow'],version:7,editable:true},{id:'sales',label:'销售',description:'默认跟进线索',defaultScope:'own',permissions:['lead.follow'],version:3,editable:true},{id:'superadmin',label:'超级管理员',permissions:[],version:1,editable:false}],staff=[];const perms=[{id:'session.attendance',label:'登记考勤'},{id:'lead.follow',label:'跟进线索'},{id:'lead.create',label:'创建线索'},{id:'employee.create',label:'创建员工'},{id:'account.update',label:'修改账号'},{id:'role.grant',label:'管理角色'}];let patch;b.respond(async(url,options={})=>{const endpoint=String(url);if(endpoint.endsWith('/v1/roles'))return{ok:true,status:200,json:async()=>({roles,permissions:perms,reservedPermissions:['employee.create','account.update','role.grant']})};if(endpoint.endsWith('/v1/admin/users'))return{ok:true,status:200,json:async()=>({users:staff})};if(endpoint.endsWith('/v1/admin/roles/teacher')){patch={options,body:JSON.parse(options.body)};roles=roles.map(r=>r.id==='teacher'?{...r,permissions:patch.body.permissions,version:8}:r);return{ok:true,status:200,json:async()=>({role:roles[0],affectedUsers:2,changed:true})}}if(endpoint.endsWith('/v1/auth/me'))return{ok:true,status:200,json:async()=>({user:admin,csrfToken:'private-csrf'})};return{ok:false,status:500,json:async()=>({code:'ERROR'})}});await b.run("employeeAuth.openDirectory('permissions')");assert.match(b.elements.get('#view').innerHTML,/默认职责/);assert.match(b.elements.get('#view').innerHTML,/当前授权以勾选项和数据范围为准/);assert.match(b.elements.get('#view').innerHTML,/name=\"ea-role-permission\"/);assert.match(b.elements.get('#view').innerHTML,/仅超级管理员角色/);assert.match(b.elements.get('#view').innerHTML,/data-mixed=\"true\"/);b.run("employeeAuth.toggleRolePermission('lead.create',true)");b.run("employeeAuth.selectPermissionRole('sales')");b.run("employeeAuth.selectPermissionRole('teacher')");assert.match(b.elements.get('#view').innerHTML,/data-permission=\"lead.create\"[^>]*checked/);assert.equal(await b.run('employeeAuth.saveRolePermissions()'),true);assert.deepEqual(patch.body,{permissions:['lead.create','lead.follow','session.attendance'],expectedVersion:7});assert.equal(patch.options.headers['X-CSRF-Token'],'private-csrf');assert.equal(b.run('state.page'),'permissions');assert.match(b.elements.get('#view').innerHTML,/教师 · 权限模板/);assert.match(b.messages.at(-1),/影响 2 名员工/);b.run("employeeAuth.selectPermissionRole('superadmin')");assert.match(b.elements.get('#view').innerHTML,/固定为全部权限/);assert.doesNotMatch(b.elements.get('#view').innerHTML,/保存权限更改/);assert.equal(b.run("employeeAuth.toggleRolePermission('lead.follow',false)"),false)});

test('role permission failures retain drafts and version conflicts require explicit reload',async()=>{const admin=user(['account.update','role.grant'],{roleIds:['superadmin'],scope:{type:'all'}}),b=await create(admin),roles=[{id:'teacher',label:'教师',permissions:[],version:4,editable:true}];let reloads=0;b.respond(async(url,options={})=>{const endpoint=String(url);if(endpoint.endsWith('/v1/roles')){reloads++;return{ok:true,status:200,json:async()=>({roles,permissions:[{id:'lead.follow',label:'跟进线索'}]})}}if(endpoint.endsWith('/v1/admin/users'))return{ok:true,status:200,json:async()=>({users:[]})};return{ok:false,status:409,json:async()=>({code:'ROLE_VERSION_CONFLICT'})}});await b.run("employeeAuth.openDirectory('permissions')");b.run("employeeAuth.toggleRolePermission('lead.follow',true)");assert.equal(await b.run('employeeAuth.saveRolePermissions()'),false);assert.match(b.elements.get('#view').innerHTML,/版本冲突/);assert.match(b.elements.get('#view').innerHTML,/lead.follow/);assert.equal(reloads,1);await b.run('employeeAuth.reloadRolePermissions()');assert.equal(reloads,2);assert.doesNotMatch(b.elements.get('#view').innerHTML,/有未保存的角色权限更改/)});

