test('role permission save reports committed change when directory readback fails',async()=>{const admin=user(['account.update','role.grant'],{roleIds:['superadmin'],scope:{type:'all'}}),b=await create(admin);let patches=0,role={id:'teacher',label:'教师',permissions:[],version:2,editable:true};b.respond(async(url,options={})=>{const endpoint=String(url);if(endpoint.endsWith('/v1/roles')){if(patches)return{ok:false,status:500,json:async()=>({code:'ERROR'})};return{ok:true,status:200,json:async()=>({roles:[role],permissions:[{id:'lead.follow',label:'跟进线索'}]})}}if(endpoint.endsWith('/v1/admin/users'))return{ok:true,status:200,json:async()=>({users:[]})};if(endpoint.endsWith('/v1/admin/roles/teacher')){patches++;return{ok:true,status:200,json:async()=>({role:{...role,permissions:['lead.follow'],version:3},affectedUsers:1,changed:true})}}return{ok:false,status:500,json:async()=>({code:'ERROR'})}});await b.run("employeeAuth.openDirectory('permissions')");b.run("employeeAuth.toggleRolePermission('lead.follow',true)");assert.equal(await b.run('employeeAuth.saveRolePermissions()'),true);assert.match(b.elements.get('#view').innerHTML,/角色权限已保存，但最新目录暂时加载失败/);assert.doesNotMatch(b.elements.get('#view').innerHTML,/未保存的角色权限更改/);assert.equal(patches,1)});

