test('password change rejects nine characters and permits ten across the first-login form',async()=>{
 for(const [password,accepted]of [['Abc!23456',false],['Abcd!23456',true]]){
  const b=await create(user(['dashboard.read'],{mustChangePassword:true}));
  const html=b.elements.get('#employee-auth-gate').innerHTML;
  assert.equal((html.match(/minlength="10"/g)||[]).length,2);
  assert.match(html,/至少 10 位/);assert.doesNotMatch(html,/至少 14 位|minlength="14"/);
  b.ctx.document.querySelector('#ea-current').value='Existing-Test!23456';
  b.ctx.document.querySelector('#ea-new').value=password;
  b.ctx.document.querySelector('#ea-repeat').value=password;
  await b.run('employeeAuth.password()');
  const changed=b.requests.filter(r=>r.url.endsWith('/v1/auth/password'));
  assert.equal(changed.length,accepted?1:0);
  if(accepted){assert.equal(JSON.parse(changed[0].options.body).newPassword,password);assert.equal(b.classes.has('employee-auth-locked'),false);assert.equal(b.run('workflowCurrentActor().mustChangePassword'),false);assert.equal(b.run('state.page'),'home');assert.equal(b.requests.filter(r=>r.url.endsWith('/v1/auth/login')).length,0);assert.equal(b.messages.at(-1),'密码已修改')}
  else assert.match(b.elements.get('#employee-auth-gate').innerHTML,/密码至少 10 位/);
 }
});

function authResponse(body,status=200){return {ok:status<400,status,json:async()=>body}}
test('saving a role held by the administrator preserves the edited role after the session version refresh',async()=>{
 const admin=user(['role.grant','account.update'],{roleIds:['superadmin','sales'],scope:{type:'all'},version:3}),b=await create(admin);
 let role={id:'sales',label:'销售',permissions:[],version:2,editable:true};
 const roleDirectory=()=>({roles:[{id:'teacher',label:'教师',permissions:[],version:1,editable:true},role],permissions:[{id:'lead.follow',label:'跟进线索'}]});
 b.respond(async(url,options={})=>{
  const endpoint=String(url);
  if(endpoint.endsWith('/v1/roles'))return authResponse(roleDirectory());
  if(endpoint.endsWith('/v1/admin/users'))return authResponse({users:[]});
  if(endpoint.endsWith('/v1/admin/roles/sales')){role={...role,permissions:JSON.parse(options.body).permissions,version:3};return authResponse({role,affectedUsers:1,changed:true})}
  if(endpoint.endsWith('/v1/auth/me'))return authResponse({user:{...admin,version:4},csrfToken:'updated-csrf'});
  return authResponse({code:'ERROR'},500);
 });
 await b.run("employeeAuth.openDirectory('permissions')");
 b.run("employeeAuth.selectPermissionRole('sales')");
 b.run("employeeAuth.toggleRolePermission('lead.follow',true)");
 assert.equal(await b.run('employeeAuth.saveRolePermissions()'),true);
 assert.equal(b.run('state.page'),'permissions');
 assert.match(b.elements.get('#view').innerHTML,/销售 · 权限模板/);
 assert.match(b.elements.get('#view').innerHTML,/data-permission="lead.follow" checked/);
 assert.equal(b.run('workflowCurrentActor().version'),4);
});
function fillLogin(b,{username='employee1',password='Existing-Test!23456',code='123456',remember=false}={}){b.ctx.document.querySelector('#ea-username').value=username;b.ctx.document.querySelector('#ea-password').value=password;b.ctx.document.querySelector('#ea-captcha-code').value=code;b.ctx.document.querySelector('#ea-remember').checked=remember;}
test('login automatically loads only server-issued captcha and sends challenge plus optional remembered session',async()=>{const b=await create(null,{unauthorized:true});assert.equal(b.requests.filter(r=>r.url.endsWith('/v1/auth/captcha')).length,1);const gate=b.elements.get('#employee-auth-gate').innerHTML;assert.match(gate,/name="username"[^>]*autocomplete="username"/);assert.match(gate,/name="password"[^>]*autocomplete="current-password"/);assert.match(gate,/maxlength="6"/);assert.match(gate,/inputmode="numeric"/);assert.match(gate,/刷新数字验证码/);assert.match(gate,/记住密码/);assert.match(gate,/30 天内保持登录，密码由浏览器保存/);assert.doesNotMatch(gate,/id="ea-remember" checked/);assert.match(b.elements.get('#ea-captcha').innerHTML,/data:image\/png;base64/);let sent;b.respond(async(url,options={})=>{sent={url:String(url),body:JSON.parse(options.body||'{}')};return authResponse({user:user(['dashboard.read']),csrfToken:'private-login-csrf',expiresAt:'2099-01-01'})});fillLogin(b,{remember:true});assert.equal(await b.run('employeeAuth.login()'),true);assert.equal(sent.body.captchaId,'test-captcha');assert.equal(sent.body.captchaCode,'123456');assert.equal(sent.body.remember,true);assert.equal(sent.body.client,'browser');assert.equal(b.classes.has('employee-auth-locked'),false);assert.deepEqual(JSON.parse(b.storage.get('siyue-employee-login-preference')),{username:'employee1',remember:true});for(const stored of b.storage.values()){assert.ok(!String(stored).includes('Existing-Test!23456'));assert.ok(!String(stored).includes('private-login-csrf'));assert.ok(!String(stored).includes('123456'))}});
test('captcha failure consumes old challenge and refreshes image while preserving account and remember choice',async()=>{const b=await create(null,{unauthorized:true});let logins=0,refreshes=0,posted=[];b.respond(async(url,options={})=>{if(String(url).endsWith('/captcha')){refreshes++;return authResponse(captchaFixture('renewed-'+refreshes))}logins++;posted.push(JSON.parse(options.body));return logins===1?authResponse({code:'CAPTCHA_INVALID'},400):authResponse({user:user(['dashboard.read']),csrfToken:'new-csrf',expiresAt:'2099-01-01'})});fillLogin(b,{username:'employee1',remember:true,code:'999999'});assert.equal(await b.run('employeeAuth.login()'),false);assert.equal(refreshes,1);assert.match(b.elements.get('#employee-auth-gate').innerHTML,/验证码错误或已失效/);assert.match(b.elements.get('#employee-auth-gate').innerHTML,/value="employee1"/);assert.match(b.elements.get('#employee-auth-gate').innerHTML,/id="ea-remember" checked/);assert.doesNotMatch(b.elements.get('#employee-auth-gate').innerHTML,/Existing-Test!23456|999999/);fillLogin(b,{remember:true,code:'000001'});assert.equal(await b.run('employeeAuth.login()'),true);assert.equal(posted[0].captchaId,'test-captcha');assert.equal(posted[1].captchaId,'renewed-1');assert.equal(posted[1].captchaCode,'000001')});
test('incomplete and expired captcha never submit login; refresh has clear status and no locally generated substitute',async()=>{const b=await create(null,{unauthorized:true});let posted=0;b.respond(async(url,options={})=>{if(options.method==='POST')posted++;return authResponse(captchaFixture('fresh'))});fillLogin(b,{code:'12345'});assert.equal(await b.run('employeeAuth.login()'),false);assert.equal(posted,0);assert.match(b.elements.get('#employee-auth-gate').innerHTML,/6 位数字验证码/);b.run('Date.now=()=>'+(Date.now()+180000));fillLogin(b);assert.equal(await b.run('employeeAuth.login()'),false);assert.equal(posted,0);assert.match(b.elements.get('#employee-auth-gate').innerHTML,/验证码已过期/);b.respond(async()=>authResponse({id:'unsafe',image:'https://outside.invalid/captcha.svg',expiresAt:'2099-01-01'}));await b.run('employeeAuth.refreshCaptcha()');assert.match(b.elements.get('#ea-captcha').innerHTML,/验证码获取失败/);assert.doesNotMatch(b.elements.get('#ea-captcha').innerHTML,/outside.invalid/);assert.equal(b.elements.get('#ea-login-submit').disabled,true)});
test('remembered account survives reload but unchecking removes local preference and never stores password',async()=>{const saved=new Map([['siyue-employee-login-preference',JSON.stringify({username:'saved-account',remember:true})]]),b=await create(null,{unauthorized:true,storage:saved});assert.match(b.elements.get('#employee-auth-gate').innerHTML,/value="saved-account"/);assert.match(b.elements.get('#employee-auth-gate').innerHTML,/id="ea-remember" checked/);fillLogin(b,{username:'saved-account',password:'NeverPersist!123',remember:false});b.run('employeeAuth.remember(false)');assert.equal(saved.has('siyue-employee-login-preference'),false);b.respond(async()=>authResponse({user:user(['dashboard.read']),csrfToken:'NeverPersistToken',expiresAt:'2099-01-01'}));assert.equal(await b.run('employeeAuth.login()'),true);for(const stored of saved.values())assert.ok(!String(stored).includes('NeverPersist'));const fresh=await create(null,{unauthorized:true,storage:saved});assert.doesNotMatch(fresh.elements.get('#employee-auth-gate').innerHTML,/saved-account|id="ea-remember" checked/)});
test('first-password change enters workbench directly using rotated CSRF while normal change requires login',async()=>{const first=await create(user(['dashboard.read'],{mustChangePassword:true}));first.ctx.document.querySelector('#ea-current').value='Original!12345';first.ctx.document.querySelector('#ea-new').value='Updated!12345';first.ctx.document.querySelector('#ea-repeat').value='Updated!12345';assert.equal(await first.run('employeeAuth.password()'),true);assert.equal(first.classes.has('employee-auth-locked'),false);assert.equal(first.run('state.page'),'home');assert.equal(first.run('workflowCurrentActor().version'),2);await first.run("employeeAuth.request('v1/verification',{method:'POST',body:{}})");assert.equal(first.requests.at(-1).options.headers['X-CSRF-Token'],'rotated-csrf');assert.equal(first.requests.filter(r=>r.url.endsWith('/login')).length,0);const normal=await create(user(['dashboard.read']));normal.ctx.document.querySelector('#ea-current').value='Original!12345';normal.ctx.document.querySelector('#ea-new').value='Updated!12345';normal.ctx.document.querySelector('#ea-repeat').value='Updated!12345';assert.equal(await normal.run('employeeAuth.password()'),true);assert.equal(normal.classes.has('employee-auth-locked'),true);assert.equal(normal.run('workflowCurrentActor()'),null);assert.match(normal.elements.get('#employee-auth-gate').innerHTML,/密码已修改，请使用新密码登录/)});
test('late password and captcha responses cannot restore an expired session or replace a newer identity',async()=>{const account=user(['dashboard.read'],{mustChangePassword:true}),b=await create(account);let finish;b.respond(async()=>new Promise(resolve=>finish=resolve));b.ctx.document.querySelector('#ea-current').value='Original!12345';b.ctx.document.querySelector('#ea-new').value='Updated!12345';b.ctx.document.querySelector('#ea-repeat').value='Updated!12345';const pending=b.run('employeeAuth.password()');b.respond(async url=>String(url).endsWith('/captcha')?authResponse(captchaFixture()):authResponse({code:'SESSION_EXPIRED'},401));await assert.rejects(b.run('employeeAuth.refresh()'));finish(authResponse({changed:true,reauthenticate:false,user:{...account,mustChangePassword:false,version:2},csrfToken:'stale-token',expiresAt:'2099-01-01'}));await pending;assert.equal(b.classes.has('employee-auth-locked'),true);assert.equal(b.run('workflowCurrentActor()'),null);const logged=await create(null,{unauthorized:true});let captchaFinish;logged.respond(async()=>new Promise(resolve=>captchaFinish=resolve));const captchaPending=logged.run('employeeAuth.refreshCaptcha()');logged.respond(async()=>authResponse({user:user(['dashboard.read']),csrfToken:'fresh-session',expiresAt:'2099-01-01'}));await logged.run('employeeAuth.refresh()');captchaFinish(authResponse(captchaFixture('late-image')));await captchaPending;assert.equal(logged.classes.has('employee-auth-locked'),false);assert.equal(logged.run('workflowCurrentActor().id'),'real-employee-1')});

test('employee archive requires inline confirmation, sends CSRF and trimmed reason, then keeps a read-only archive profile',async()=>{
 const admin=user(['account.update','audit.query'],{roleIds:['superadmin'],scope:{type:'all'}}),b=await create(admin),staff=[admin,{id:'staff-archive',name:'离职员工',username:'former',employeeNo:'F01',roleIds:['teacher'],scope:{type:'own'},disabled:false,mustChangePassword:false},{id:'staff-old',name:'历史员工',username:'old',employeeNo:'F00',roleIds:['teacher'],scope:{type:'own'},disabled:true,mustChangePassword:false,archivedAt:'2026-01-02T03:04:05Z',archivedBy:'private-admin-id',archiveReason:'离职交接'}];let archiveRequest,mutations=0;
 b.respond(async(url,options={})=>{const endpoint=String(url);if(endpoint.endsWith('/v1/roles'))return{ok:true,status:200,json:async()=>({roles:[{id:'superadmin',label:'超级管理员'},{id:'teacher',label:'教师'}],permissions:[]})};if(endpoint.endsWith('/v1/admin/users')&&options.method==='GET')return{ok:true,status:200,json:async()=>({users:staff})};if(endpoint.endsWith('/v1/admin/users/staff-archive/archive')){mutations++;archiveRequest={url:endpoint,options,body:JSON.parse(options.body)};return{ok:true,status:200,json:async()=>({archived:true,user:{...staff[1],disabled:true,version:2,archivedAt:'2026-10-11T01:02:03Z',archivedBy:admin.id,archiveReason:'合同结束'}})}};return{ok:false,status:500,json:async()=>({code:'ERROR'})}});
 await b.run('employeeAuth.openAccounts()');let html=b.elements.get('#view').innerHTML;assert.match(html,/value="active" selected/);assert.match(html,/离职员工/);assert.doesNotMatch(html,/历史员工/);assert.doesNotMatch(html,/private-admin-id/);assert.doesNotMatch(html,/employeeAuth\.beginArchive\('real-employee-1'\)/);assert.equal(b.run("employeeAuth.beginArchive('real-employee-1')"),false);b.run("employeeAuth.toggleAccount('staff-archive')");assert.match(b.elements.get('#view').innerHTML,/在岗/);assert.equal(b.run("employeeAuth.beginArchive('staff-archive')"),true);assert.match(b.elements.get('#view').innerHTML,/确认将 离职员工 标记为离职归档/);assert.equal(b.requests.filter(r=>r.url.endsWith('/staff-archive/archive')).length,0);b.run("employeeAuth.setArchiveReason('  合同结束  ')");assert.equal(await b.run("employeeAuth.archiveEmployee('staff-archive')"),true);assert.equal(archiveRequest.options.method,'POST');assert.deepEqual(archiveRequest.body,{reason:'合同结束'});assert.equal(archiveRequest.options.headers['X-CSRF-Token'],'private-csrf');html=b.elements.get('#view').innerHTML;assert.match(html,/历史员工/);assert.match(html,/离职员工/);assert.match(html,/离职时间：/);assert.match(html,/离职原因：合同结束/);assert.doesNotMatch(html,/编辑账号与权限/);assert.doesNotMatch(html,/重置此员工密码/);assert.doesNotMatch(html,/employeeAuth\.beginArchive\('staff-archive'\)/);assert.equal(await b.run("employeeAuth.resetPassword('staff-archive')"),false);b.run("employeeAuth.editAccount('staff-archive')");assert.equal(b.run('state.page'),'staff');assert.equal(mutations,1)
});

test('employee archive failure keeps inline confirmation and exposes server reason without writing on self',async()=>{
 const admin=user(['account.update'],{roleIds:['superadmin'],scope:{type:'all'}}),b=await create(admin),staff={id:'staff-last',name:'最后管理员',username:'last',roleIds:['superadmin'],scope:{type:'all'},disabled:false,archivedAt:null};let writes=0;b.respond(async(url,options={})=>{const endpoint=String(url);if(endpoint.endsWith('/v1/roles'))return{ok:true,status:200,json:async()=>({roles:[{id:'superadmin',label:'超级管理员'}],permissions:[]})};if(endpoint.endsWith('/v1/admin/users')&&options.method==='GET')return{ok:true,status:200,json:async()=>({users:[staff]})};if(endpoint.endsWith('/staff-last/archive')){writes++;return{ok:false,status:409,json:async()=>({code:'LAST_SUPERADMIN'})}};return{ok:false,status:500,json:async()=>({code:'ERROR'})}});await b.run('employeeAuth.openAccounts()');b.run("employeeAuth.toggleAccount('staff-last')");assert.equal(b.run("employeeAuth.beginArchive('staff-last')"),true);assert.equal(await b.run("employeeAuth.archiveEmployee('staff-last')"),false);assert.equal(writes,1);assert.match(b.elements.get('#view').innerHTML,/至少保留一名可用的超级管理员/);assert.match(b.elements.get('#view').innerHTML,/确认归档/);assert.equal(b.run("employeeAuth.beginArchive('real-employee-1')"),false)
});

test('employee archive omits an empty optional reason from request body',async()=>{
 const admin=user(['account.update'],{roleIds:['superadmin'],scope:{type:'all'}}),b=await create(admin),target={id:'staff-no-reason',name:'离职员工',username:'former',roleIds:['teacher'],scope:{type:'own'},disabled:false};let body;b.respond(async(url,options={})=>{const endpoint=String(url);if(endpoint.endsWith('/v1/roles'))return{ok:true,status:200,json:async()=>({roles:[{id:'superadmin',label:'超级管理员'},{id:'teacher',label:'教师'}],permissions:[]})};if(endpoint.endsWith('/v1/admin/users')&&options.method==='GET')return{ok:true,status:200,json:async()=>({users:[target]})};if(endpoint.endsWith('/staff-no-reason/archive')){body=JSON.parse(options.body);return{ok:true,status:200,json:async()=>({archived:true,user:{...target,disabled:true,archivedAt:'2026-10-11T00:00:00Z',archiveReason:null}})}};return{ok:false,status:500,json:async()=>({code:'ERROR'})}});await b.run('employeeAuth.openAccounts()');b.run("employeeAuth.toggleAccount('staff-no-reason')");b.run("employeeAuth.beginArchive('staff-no-reason')");assert.equal(await b.run("employeeAuth.archiveEmployee('staff-no-reason')"),true);assert.deepEqual(body,{});
});

test('archived employee is excluded from permission editing and cannot be selected directly',async()=>{
 const admin=user(['account.update','role.grant'],{roleIds:['superadmin'],scope:{type:'all'}}),b=await create(admin),archived={id:'archived-user',name:'已归档员工',username:'archived',roleIds:['teacher'],scope:{type:'own'},disabled:true,archivedAt:'2026-01-01T00:00:00Z',archiveReason:'离职'};b.respond(async(url,options={})=>String(url).endsWith('/v1/roles')?{ok:true,status:200,json:async()=>({roles:[{id:'teacher',label:'教师',permissions:[]}],permissions:[]})}:{ok:true,status:200,json:async()=>({users:[archived]})});await b.run("employeeAuth.openDirectory('permissions')");assert.doesNotMatch(b.elements.get('#view').innerHTML,/已归档员工/);b.run("employeeAuth.selectPermissionEmployee('archived-user')");assert.doesNotMatch(b.elements.get('#view').innerHTML,/员工单项权限/);assert.equal(b.run('state.page'),'permissions')
});


test('non-superadmin cannot open or submit employee archive',async()=>{const b=await create(user(['account.update']));let writes=0;b.respond(async()=>{writes++;return{ok:false,status:403,json:async()=>({code:'FORBIDDEN'})}});assert.equal(b.run("employeeAuth.beginArchive('staff-1')"),false);assert.equal(await b.run("employeeAuth.archiveEmployee('staff-1')"),false);assert.equal(writes,0)});


test('archived employee audit gives a readable action and reason',async()=>{
 const b=await create(user(['audit.read']));b.respond(async()=>authResponse({events:[{id:'archive-event',at:'2026-10-11T01:00:00Z',actorName:'管理员',targetName:'离职员工',action:'account.archive',outcome:'success',summary:{archived:true,archiveReason:'交接完成 <script>'}}]}));await b.run('employeeAuth.openAudit()');b.run('employeeAuth.toggleAudit(0)');const html=b.elements.get('#view').innerHTML;assert.match(html,/员工离职归档/);assert.match(html,/历史档案保留/);assert.match(html,/离职原因：交接完成 &lt;script&gt;/);assert.doesNotMatch(html,/<script>|account.archive/);
});
test('default employee list includes new employees awaiting first password change',async()=>{
 const b=await create(user(['account.update'],{roleIds:['superadmin'],scope:{type:'all'}}));b.respond(async url=>String(url).endsWith('/v1/roles')?authResponse({roles:[],permissions:[]}):authResponse({users:[{id:'pending-new',name:'刚入职员工',roleIds:['sales'],scope:{type:'own'},mustChangePassword:true,disabled:false}]}));await b.run('employeeAuth.openAccounts()');const html=b.elements.get('#view').innerHTML;assert.match(html,/刚入职员工/);assert.match(html,/在岗 1/);assert.match(html,/待改初始密码 1/);
});

test('employee departure command is searchable only by superadmin and opens account selection',async()=>{
 const admin=await create(user(['account.update'],{roleIds:['superadmin'],scope:{type:'all'}}));assert.equal(admin.run("commandAllowed(commandWorkflows.find(x=>x.id==='account.employee.archive'))"),true);assert.match(admin.run("JSON.stringify(commandWorkflows.find(x=>x.id==='account.employee.archive').words)"),/注销账号/);const employee=await create(user(['staff.read']));assert.equal(employee.run("commandAllowed(commandWorkflows.find(x=>x.id==='account.employee.archive'))"),false);
});
